<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class Insight extends Model{protected $fillable=['insight_rule_id','floor_id','survey_area_id','survey_id','title','classification','severity','confidence','status','period_start','period_end','evidence','triggered_values','thresholds','limitations','recommendation','calculation_version','evidence_hash','generated_at','reviewed_at','reviewed_by','resolved_at'];protected function casts():array{return ['period_start'=>'datetime','period_end'=>'datetime','evidence'=>'array','triggered_values'=>'array','thresholds'=>'array','limitations'=>'array','generated_at'=>'datetime','reviewed_at'=>'datetime','resolved_at'=>'datetime'];}public function rule(){return $this->belongsTo(InsightRule::class,'insight_rule_id');}public function floor(){return $this->belongsTo(Floor::class);}public function surveyArea(){return $this->belongsTo(SurveyArea::class);}public function survey(){return $this->belongsTo(Survey::class);}public function actions(){return $this->hasMany(ActionItem::class);}}
